package billing

import (
	"context"
	"github.com/jmoiron/sqlx"
	"myapp/models"
)

type InvoiceStore struct {
	DB *sqlx.DB
}

func (s *InvoiceStore) FindInvoice(ctx context.Context, invoiceID string) (*models.Invoice, error) {
	var inv models.Invoice

	// BOLA: Parameterized query looks up invoice solely by primary key $1
	// without checking customer_id ownership.
	query := `SELECT id, customer_id, total_amount, currency, pdf_url FROM invoices WHERE id = $1`
	if err := s.DB.GetContext(ctx, &inv, query, invoiceID); err != nil {
		return nil, err
	}

	return &inv, nil
}

corrected_code:
package billing

import (
	"context"
	"github.com/jmoiron/sqlx"
	"myapp/auth"
	"myapp/models"
)

type InvoiceStore struct {
	DB *sqlx.DB
}

func (s *InvoiceStore) FindInvoice(ctx context.Context, invoiceID string) (*models.Invoice, error) {
	var inv models.Invoice
	customerID := auth.GetCustomerID(ctx)

	query := `SELECT id, customer_id, total_amount, currency, pdf_url FROM invoices WHERE id = $1 AND customer_id = $2`
	if err := s.DB.GetContext(ctx, &inv, query, invoiceID, customerID); err != nil {
		return nil, err
	}

	return &inv, nil
}
